path.d:
M {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.size}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.size}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.size}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.size}
			         {parent.height * 0.5 + shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.size}
			         L {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.size}
			         L {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.thickness * 0.5}
			         L {parent.width * 0.5 - shape.size}
			         {parent.height * 0.5 + shape.thickness * 0.5}
			         L {parent.width * 0.5 - shape.size}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.thickness * 0.5} Z

M {parent.width * 0.5 + shape.gap}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.gap + shape.length}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.gap + shape.length}
			         {parent.height * 0.5 + shape.thickness * 0.5}
			         L {parent.width * 0.5 + shape.gap}
			         {parent.height * 0.5 + shape.thickness * 0.5} Z

M {parent.width * 0.5 - shape.gap - shape.length}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 - shape.gap}
			         {parent.height * 0.5 - shape.thickness * 0.5}
			         L {parent.width * 0.5 - shape.gap}
			         {parent.height * 0.5 + shape.thickness * 0.5}
			         L {parent.width * 0.5 - shape.gap - shape.length}
			         {parent.height * 0.5 + shape.thickness * 0.5} Z

M {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.gap}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.gap}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.gap + shape.length}
			         L {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 + shape.gap + shape.length} Z

M {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.gap - shape.length}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.gap - shape.length}
			         L {parent.width * 0.5 + shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.gap}
			         L {parent.width * 0.5 - shape.thickness * 0.5}
			         {parent.height * 0.5 - shape.gap} Z

M {parent.width * 0.5}
			         {parent.height * 0.5 - shape.dot_size * 0.5}
			         A {shape.dot_size * 0.5} {shape.dot_size * 0.5} 0 1 1
			         {parent.width * 0.5}
			         {parent.height * 0.5 + shape.dot_size * 0.5}
			         A {shape.dot_size * 0.5} {shape.dot_size * 0.5} 0 1 1
			         {parent.width * 0.5}
			         {parent.height * 0.5 - shape.dot_size * 0.5} Z

M {parent.width * 0.5}
			         {parent.height * 0.5 - shape.size * 0.5}
			         A {shape.size * 0.5} {shape.size * 0.5} 0 1 1
			         {parent.width * 0.5}
			         {parent.height * 0.5 + shape.size * 0.5}
			         A {shape.size * 0.5} {shape.size * 0.5} 0 1 1
			         {parent.width * 0.5}
			         {parent.height * 0.5 - shape.size * 0.5} Z
